const fs = require('fs');
const path = require('path');

const input = $input.first();
const rawJson = (input && input.json) || {};

// 1. Nhận diện nguồn gọi: Webhook vs Execute Workflow
let triggerSource = 'executeWorkflow';
let rawBody = {};

try {
  const trigWebhook = $('Webhook Trigger (workspace-resolve)').first();
  if (trigWebhook && trigWebhook.json) {
    triggerSource = 'webhook';
    rawBody = trigWebhook.json.body || trigWebhook.json;
  }
} catch (e) {}

if (triggerSource !== 'webhook') {
  try {
    const trigExec = $('Execute Workflow Trigger').first();
    if (trigExec && trigExec.json) {
      triggerSource = 'executeWorkflow';
      rawBody = trigExec.json.body?.params || trigExec.json.body || trigExec.json.params || trigExec.json;
    }
  } catch (e) {}
}

// Fallback merge với rawJson
const payload = Object.assign({}, rawJson, rawBody);

const rawKey = payload.issueKey || '';
const rawProject = (payload.project || '').trim();
const targetPath = (payload.targetPath || payload.relativePath || payload.filePath || '').trim();
const readContent = Boolean(payload.readContent);
const fileFilter = (payload.fileFilter || '').toLowerCase().trim();
const userName = payload.userName || 'User';

// 2. Chuẩn hoá issueKey (chấp nhận cả 'sprint' hoặc mã ticket ABCD-1234)
let issueKey = '';
if (rawKey.toLowerCase() === 'sprint') {
  issueKey = 'sprint';
} else {
  const match = String(rawKey).match(/([A-Z][A-Z0-9]*-\d+)/i);
  issueKey = match ? match[1].toUpperCase() : '';
}

if (!issueKey) {
  const errMsg = `🚨 **[Lỗi Tham Số]** Không tìm thấy mã Jira \`issueKey\` hợp lệ (VD: G3PTP-17396 hoặc 'sprint').`;
  return [{
    json: {
      found: false,
      isError: true,
      errorType: 'INVALID_ISSUE_KEY',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// 3. Phân giải danh sách Base Folders khả dĩ
const candidateFolders = [];
const projectRoot = ($env && $env.AGENT_WORKSPACE_DIR) || '/Users/qa-quangnt/Desktop/Project/Test/agent-skills';

// A. Đường dẫn tuyệt đối nếu user truyền full path
if (rawProject && path.isAbsolute(rawProject) && fs.existsSync(rawProject)) {
  candidateFolders.push(path.resolve(rawProject));
}

// B. Tra cứu từ projects.json
const projectsJsonPath = path.join(projectRoot, 'projects.json');
if (fs.existsSync(projectsJsonPath)) {
  try {
    const pMap = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf8'));
    if (rawProject && pMap[rawProject.toLowerCase()]) {
      candidateFolders.push(path.resolve(pMap[rawProject.toLowerCase()]));
    }
    for (const [pKey, pVal] of Object.entries(pMap)) {
      const pResolved = path.resolve(pVal);
      if (!candidateFolders.includes(pResolved)) {
        candidateFolders.push(pResolved);
      }
    }
  } catch (e) {}
}

// C. Tra cứu từ PROJECT_SCAN_DIRS trong $env
const scanDirsRaw = ($env && $env.PROJECT_SCAN_DIRS) || '';
if (scanDirsRaw) {
  const scanDirs = scanDirsRaw.split(',').map(s => s.trim().replace(/^[\"']|[\"']$/g, '')).filter(Boolean);
  for (const sDir of scanDirs) {
    const resolved = path.resolve(sDir);
    if (!candidateFolders.includes(resolved)) {
      candidateFolders.push(resolved);
    }
  }
}

// D. Luôn bổ sung projectRoot hiện tại
if (!candidateFolders.includes(projectRoot)) {
  candidateFolders.push(projectRoot);
}

// 4. Dò tìm mục tiêu: targetPath trong workspace/[issueKey]
let foundPath = null;
let isDirectory = false;
let resolvedProjectRoot = '';
let resolvedWorkspaceDir = '';
const checkedPaths = [];

for (const folder of candidateFolders) {
  // Kiểm tra 1: folder/workspace/[issueKey]/[targetPath]
  const p1 = targetPath
    ? path.join(folder, 'workspace', issueKey, targetPath)
    : path.join(folder, 'workspace', issueKey);
  checkedPaths.push(p1);

  if (fs.existsSync(p1)) {
    foundPath = p1;
    resolvedProjectRoot = folder;
    resolvedWorkspaceDir = path.join(folder, 'workspace', issueKey);
    break;
  }

  // Kiểm tra 2: nếu folder là cluster chứa nhiều repo con (VD: Desktop/Project/3.1)
  try {
    if (fs.existsSync(folder) && fs.statSync(folder).isDirectory()) {
      const subEntries = fs.readdirSync(folder, { withFileTypes: true });
      for (const sub of subEntries) {
        if (sub.isDirectory() && !sub.name.startsWith('.')) {
          const subFolder = path.join(folder, sub.name);
          const p2 = targetPath
            ? path.join(subFolder, 'workspace', issueKey, targetPath)
            : path.join(subFolder, 'workspace', issueKey);
          checkedPaths.push(p2);
          if (fs.existsSync(p2)) {
            foundPath = p2;
            resolvedProjectRoot = subFolder;
            resolvedWorkspaceDir = path.join(subFolder, 'workspace', issueKey);
            break;
          }
        }
      }
    }
  } catch (e) {}

  if (foundPath) break;
}

// 5. Nếu KHÔNG tìm thấy
if (!foundPath) {
  const errMsg = `🚨 **[Không Tìm Thấy File/Thư Mục Local]**\n` +
                 `> **IssueKey:** \`${issueKey}\`\n` +
                 `> **Mục tiêu tìm kiếm:** \`${targetPath || 'workspace/' + issueKey}\`\n` +
                 `> **Project/Cluster:** \`${rawProject || 'Tự động dò quét'}\`\n` +
                 `> **Các vị trí đã quét:**\n` +
                 checkedPaths.slice(0, 5).map(p => `- \`${p}\``).join('\n') + '\n\n' +
                 `*Gợi ý: Hãy kiểm tra file đã được tạo tại đúng quy chuẩn \`[folder]/workspace/${issueKey}/...\` chưa.*`;
  return [{
    json: {
      found: false,
      isError: true,
      errorType: 'PATH_NOT_FOUND',
      issueKey,
      project: rawProject,
      targetPath,
      checkedPaths,
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// 6. Xử lý khi TÌM THẤY
const stat = fs.statSync(foundPath);
isDirectory = stat.isDirectory();

let fileContent = '';
let matchedFiles = [];
let diagramPaths = [];

if (isDirectory) {
  // Quét danh sách file trong thư mục (cả cấp 1 và subfolders như steps/)
  try {
    const collectFiles = (dir) => {
      let results = [];
      const list = fs.readdirSync(dir, { withFileTypes: true });
      for (const item of list) {
        if (item.name.startsWith('.')) continue;
        const full = path.join(dir, item.name);
        if (item.isDirectory()) {
          // Quét thêm 1 cấp subfolder (VD: steps/)
          try {
            const subList = fs.readdirSync(full, { withFileTypes: true });
            for (const subItem of subList) {
              if (!subItem.isDirectory() && !subItem.name.startsWith('.')) {
                results.push(path.join(full, subItem.name));
              }
            }
          } catch (e) {}
        } else {
          results.push(full);
        }
      }
      return results;
    };

    const allFiles = collectFiles(foundPath);
    matchedFiles = allFiles.filter(absPath => {
      const f = path.basename(absPath);
      if (!fileFilter) return true;
      const lower = f.toLowerCase();
      if (fileFilter === 'istestfile' || fileFilter.includes('test')) {
        return lower.endsWith('.py') && (lower.startsWith('test') || lower.endsWith('test.py'));
      }
      if (fileFilter.includes('feature')) {
        return lower.endsWith('.feature');
      }
      return lower.includes(fileFilter);
    }).map(f => path.relative(resolvedProjectRoot, f));
  } catch (e) {}
} else {
  // Nếu là FILE
  if (readContent) {
    try {
      fileContent = fs.readFileSync(foundPath, 'utf8');
    } catch (e) {}
  }
  // Quét thư mục diagrams nếu có ảnh đính kèm
  const parentDir = path.dirname(foundPath);
  const diagramDir = path.join(parentDir, 'diagrams');
  if (fs.existsSync(diagramDir)) {
    try {
      diagramPaths = fs.readdirSync(diagramDir)
        .filter(f => f.endsWith('.png') || f.endsWith('.svg'))
        .map(f => path.join(diagramDir, f));
    } catch (e) {}
  }
}

return [{
  json: {
    found: true,
    isError: false,
    issueKey,
    project: rawProject || path.basename(resolvedProjectRoot),
    targetPath,
    resolvedPath: foundPath,
    filePath: isDirectory ? null : foundPath,
    dirPath: isDirectory ? foundPath : path.dirname(foundPath),
    fileName: isDirectory ? null : path.basename(foundPath),
    fileSize: isDirectory ? null : stat.size,
    fileContent: fileContent,
    matchedFiles: matchedFiles,
    diagramPaths: diagramPaths,
    workspaceDir: resolvedWorkspaceDir,
    projectRoot: resolvedProjectRoot,
    _triggerSource: triggerSource,
    userName
  }
}];
